294				oldKey: {
295					{PointID: zeroPoint, Item: "B", Value: 10, Effective: eff},
296					{PointID: "P", Item: zeroItem, Value: 5, Effective: eff},
297					{PointID: "P", Item: zeroItem, Value: 6, Effective: eff},
298				},
299			},
300		})
301		assertOpenRejectsDuplicateLimit(t, dir, "P", zeroItem, eff)
302	}
303	
304	// 没有重复的多版本数据即使在文件中乱序保存，也照常打开并按生效时刻排序：
305	// 采样于各时刻之间的待判定样品取采样当时已生效的最近一版，边界时刻用新版；
306	// 已确认样品保存的历史判定依据原样保留，不按读入的限值重算。
307	func TestOpenUnorderedMultiVersionLimitsLoadAndConfirm(t *testing.T) {
308		dir := t.TempDir()
309		writeDiskFile(t, dir, diskState{
310			Points: openPoints(),
311			Limits: map[string][]Limit{
312				diskLimitKey("P1", openPH): {
313					// 故意按 10 日、1 日、5 日的乱序排列落盘。
314					{PointID: "P1", Item: openPH, Value: 6, Effective: at(10, 0)},
315					{PointID: "P1", Item: openPH, Value: 10, Effective: at(1, 0)},
316					{PointID: "P1", Item: openPH, Value: 7, Effective: at(5, 0)},
317				},
318			},
319			Samples: map[string]*Sample{
320				// 待判定：9/6 采样，应取 9/5 生效的 7，7 ≤ 7 达标。
321				"SP": {
322					ID: "SP", PointID: "P1", SampledAt: at(6, 0),
323					Measurements: []Measurement{{Item: openPH, Value: 7}},
324					Status:       StatusPending,
325				},
326				// 待判定：恰好 9/10 采样，采用新版 6，7 > 6 超标。
327				"SAT": {
328					ID: "SAT", PointID: "P1", SampledAt: at(10, 0),
329					Measurements: []Measurement{{Item: openPH, Value: 7}},
330					Status:       StatusPending,
331				},
332				// 已确认样品保存的是旧依据 10@9/1、判超标（9 > 10 为假，这里保存
333				// 11 > 10 超标），即使与当前限值重算结果不同也必须原样保留。
334				"SC": {
335					ID: "SC", PointID: "P1", SampledAt: at(2, 0),
336					Measurements: []Measurement{{Item: openPH, Value: 11}},
337					Status:       StatusConfirmed, Exceeded: true,
338					Results: []ItemResult{{
339						Item: openPH, Value: 11, Limit: 10,
340						LimitEffective: at(1, 0), Exceeded: true,
341					}},
342				},
343			},
344		})
345		s, err := Open(dir)
346		if err != nil {
347			t.Fatalf("无重复的乱序多版本数据应正常打开: %v", err)
348		}
349		defer s.Close()
350	
351		sp, err := s.Confirm("SP")
352		if err != nil {
353			t.Fatalf("Confirm SP: %v", err)
354		}
355		if r := sp.Results[0]; r.Limit != 7 || !r.LimitEffective.Equal(at(5, 0)) || r.Exceeded {
356			t.Fatalf("9/6 采样应取 9/5 生效的 7、等于上限达标: %+v", r)
357		}
358		sat, err := s.Confirm("SAT")
359		if err != nil {
360			t.Fatalf("Confirm SAT: %v", err)
361		}
362		if r := sat.Results[0]; r.Limit != 6 || !r.LimitEffective.Equal(at(10, 0)) || !r.Exceeded {
363			t.Fatalf("恰好生效时刻应采用新版 6 并超标: %+v", r)
364		}
365		// 历史结论原样保留：重复确认直接返回已保存依据，不重算。
366		sc, err := s.Confirm("SC")
367		if err != nil {
368			t.Fatalf("Confirm SC: %v", err)
369		}
370		if r := sc.Results[0]; r.Limit != 10 || !r.LimitEffective.Equal(at(1, 0)) ||
371			!r.Exceeded || !sc.Exceeded {
372			t.Fatalf("已确认样品的历史判定依据必须原样保留: %+v", r)
373		}
374	}
375	
376	// 文件里同时存在重复限值组和已确认样品时，仍然整次失败：
377	// 不能先读入样品、把拒绝推迟到确认时，也不重算任何历史依据。
378	func TestOpenDuplicateLimitRejectsEvenWithConfirmedSample(t *testing.T) {
379		dir := t.TempDir()
380		eff := at(1, 0)
381		writeDiskFile(t, dir, diskState{
382			Points: openPoints(),
383			Limits: map[string][]Limit{
384				diskLimitKey("P1", openPH): {
385					{PointID: "P1", Item: openPH, Value: 8, Effective: eff},
386					{PointID: "P1", Item: openPH, Value: 9, Effective: eff},
387				},
388			},
389			Samples: map[string]*Sample{
390				"SC": {
391					ID: "SC", PointID: "P1", SampledAt: at(2, 0),
392					Measurements: []Measurement{{Item: openPH, Value: 9}},
393					Status:       StatusConfirmed, Exceeded: true,
394					Results: []ItemResult{{
395						Item: openPH, Value: 9, Limit: 8,
396						LimitEffective: eff, Exceeded: true,
397					}},
398				},
399			},
400		})
401		assertOpenRejectsDuplicateLimit(t, dir, "P1", openPH, eff)
402	}
403	
404	// 打开因重复限值失败后不留下任何内部状态：把问题组修成唯一版本覆盖写回，
405	// 同一目录即可正常打开，历史样品照常可见。
406	func TestOpenDuplicateLimitRejectionLeavesNoState(t *testing.T) {
407		dir := t.TempDir()
408		eff := at(1, 0)
409		bad := diskState{
410			Points: openPoints(),
411			Limits: map[string][]Limit{
412				diskLimitKey("P1", openPH): {
413					{PointID: "P1", Item: openPH, Value: 8, Effective: eff},
414					{PointID: "P1", Item: openPH, Value: 9, Effective: eff},
415				},
416			},
417			Samples: map[string]*Sample{
418				"SP": {
419					ID: "SP", PointID: "P1", SampledAt: at(2, 0),
420					Measurements: []Measurement{{Item: openPH, Value: 7}},
421					Status:       StatusPending,
422				},
423			},
424		}
425		writeDiskFile(t, dir, bad)
426		if got, err := Open(dir); !errors.Is(err, ErrDuplicateLimitTime) || got != nil {
427			t.Fatalf("重复限值必须拒绝，got=%v err=%v", got, err)
428		}
429		good := bad
430		good.Limits[diskLimitKey("P1", openPH)] = []Limit{
431			{PointID: "P1", Item: openPH, Value: 8, Effective: eff},
432		}
433		writeDiskFile(t, dir, good)
434		s, err := Open(dir)
435		if err != nil {
436			t.Fatalf("修正为唯一版本后应正常打开: %v", err)
437		}
438		defer s.Close()
439		list, err := s.ListByPoint("P1")
440		if err != nil || len(list) != 1 || list[0].ID != "SP" {
441			t.Fatalf("修正后应能看到原有样品: %+v err=%v", list, err)
442		}
443	}
444

