180		}
181		if err := s.Close(); err != nil {
182			t.Fatalf("Close: %v", err)
183		}
184	
185		// 判定把零改成 1：对不上，整次失败；错误仍点名该项目。
186		bad := []ItemResult{
187			zeroResults[0],
188			{Item: openPH, Value: 1, Limit: 8, LimitEffective: openEff(), Exceeded: false},
189		}
190		writeDiskFile(t, dir, diskState{
191			Points: openPoints(),
192			Samples: map[string]*Sample{
193				"S1": {
194					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
195					Measurements: []Measurement{{Item: openPH, Value: 0}, {Item: openTurb, Value: 0}},
196					Status:       StatusConfirmed, Exceeded: false,
197					Results: bad,
198				},
199			},
200		})
201		assertOpenRejects(t, dir, "S1", openPH, false)
202	}
