204	// 同一项目在原测量里出现两次，是记录有误：整次打开失败。
205	func TestOpenConfirmedDuplicateMeasurement(t *testing.T) {
206		dir := t.TempDir()
207		writeDiskFile(t, dir, diskState{
208			Points: openPoints(),
209			Samples: map[string]*Sample{
210				"S1": {
211					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
212					Measurements: []Measurement{
213						{Item: openPH, Value: 9}, {Item: openPH, Value: 7},
214					},
215					Status: StatusConfirmed, Exceeded: true,
216					Results: []ItemResult{
