1003	// 零与负数的合法数值组合同样按“严格大于”判断。
1004	func TestOpenItemZeroAndNegativeFlags(t *testing.T) {
1005		cases := []struct {
1006			name         string
1007			value        float64
1008			limit        float64
1009			savedFlag    bool
1010			wantExceed   bool
1011			shouldReject bool
1012		}{
1013			{"零等于零标成超标", 0, 0, true, false, true},
1014			{"零小于正上限标成超标", 0, 4, true, false, true},
1015			{"零大于负上限却标成达标", 0, -1, false, true, true},
1016			{"负数严格大于负上限却标成达标", -5, -10, false, true, true},
1017			{"负数等于负上限标成超标", -5, -5, true, false, true},
1018			{"负数小于负上限标成达标（正常）", -10, -5, false, false, false},
1019			{"零等于零标成达标（正常）", 0, 0, false, false, false},
1020		}
1021		for _, c := range cases {
1022			t.Run(c.name, func(t *testing.T) {
1023				dir := t.TempDir()
1024				writeDiskFile(t, dir, diskState{
1025					Points: openPoints(),
1026					Samples: map[string]*Sample{
1027						"S1": {
1028							ID: "S1", PointID: "P1", SampledAt: at(10, 0),
1029							Measurements: []Measurement{{Item: openPH, Value: c.value}},
1030							// 整份标记与逐项实际结论一致，隔离出单项标记这一条核对。
1031							Status: StatusConfirmed, Exceeded: c.wantExceed,
1032							Results: []ItemResult{
1033								{Item: openPH, Value: c.value, Limit: c.limit, LimitEffective: openEff(), Exceeded: c.savedFlag},
1034							},
1035						},
1036					},
1037				})
1038				if c.shouldReject {
1039					assertOpenRejects(t, dir, "S1", openPH, false)
1040					return
1041				}
1042				s, err := Open(dir)
1043				if err != nil {
1044					t.Fatalf("标记与保存依据一致的合法数值组合应正常读入: %v", err)
1045				}
1046				defer s.Close()
1047				latest, ok, err := s.LatestResult("P1")
1048				if err != nil || !ok {
1049					t.Fatalf("正常记录应可作为最近有效结果: %+v ok=%v err=%v", latest, ok, err)
1050				}
1051				r := latest.Results[0]
1052				if r.Value != c.value || r.Limit != c.limit || r.Exceeded != c.wantExceed ||
1053					latest.Exceeded != c.wantExceed {
1054					t.Fatalf("保存的依据与标记应原样保留: %+v exceeded=%v", r, latest.Exceeded)
1055				}
1056			})
1057		}
1058	}
