1241				},
1242			},
1243		})
1244		s, err := Open(dir)
1245		if err != nil {
1246			t.Fatalf("待判定样品没有判定依据，不应核对超标标记: %v", err)
1247		}
1248		defer s.Close()
1249		if latest, ok, err := s.LatestResult("P1"); err != nil || ok {
1250			t.Fatalf("待判定样品不能成为最近有效结果: %+v ok=%v err=%v", latest, ok, err)
1251		}
1252	}
1253	
1254	// 多项样品中只有一项标记相反：整次失败并点名出问题的项目，
1255	// 且不改动原文件中的任何标记。
1256	func TestOpenOneWrongItemFlagAmongMany(t *testing.T) {
1257		dir := t.TempDir()
1258		results := []ItemResult{
1259			{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
1260			// 浊度 4 <= 4 应为达标，却保存成超标；整份标记与逐项实际结论一致（true）。
1261			{Item: openTurb, Value: 4, Limit: 4, LimitEffective: openEff(), Exceeded: true},
1262		}
1263		writeDiskFile(t, dir, diskState{
1264			Points: openPoints(),
1265			Samples: map[string]*Sample{
1266				"S1": {
1267					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
1268					Measurements: phTurbMeasurements(),
1269					Status:       StatusConfirmed, Exceeded: true,
1270					Results: results,
