// findDuplicateSampleID 扫描数据文件中 samples 对象的原始 JSON，返回第一个
// （按文件中出现顺序）重复出现的样品编号。样品集合里同一编号只能出现一次：
// 直接解进 map 时 JSON 同名键会被后一条静默覆盖，重复编号在 map 中看不出来，
// 因此必须在解码成 map 之前按原始条目核对。键文本按 JSON 解码后的完整文本
// 判断：一处直接写 "S1"、另一处把字符写成 Unicode 转义（如 "S1"）仍是
// 同一编号；条目之间隔着其他样品也一样。samples 字段缺失或为 null 时不算
// 重复（返回 ok=false，空集合照常打开）。不同样品各自包含同名测量项目与
// samples 对象的键无关，不会在这里被误判。
func findDuplicateSampleID(data []byte) (dup string, ok bool, err error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	// 进入顶层对象并找到 samples 字段；其余字段（points、limits）整值跳过，
	// 不随字段层级深入，样品内部的字段不会被当成样品编号。
	if err := skipToObjectField(dec, "samples"); err != nil {
		return "", false, err
	}
	// 键不存在（已到顶层对象末尾）：没有样品集合。
	if dec.More() {
		return "", false, fmt.Errorf("water: samples 字段后应为样品集合对象")
	}
	// samples 存在但为 null：与空集合一样可打开。
	tok, err := dec.Token()
	if err != nil {
		return "", false, err
	}
	delim, isDelim := tok.(json.Delim)
	if !isDelim || delim != '{' {
		// null、数组或标量：交给随后的正常反序列化报“读取数据文件失败”。
		return "", false, nil
	}
	seen := make(map[string]bool)
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return "", false, err
		}
		id := keyTok.(string) // 对象键一定是字符串
		var value json.RawMessage
		if err := dec.Decode(&value); err != nil {
			return "", false, err
		}
		if seen[id] {
			return id, true, nil
		}
		seen[id] = true
	}
	return "", false, nil
}

// skipToObjectField 在顶层 JSON 对象中推进到名为 field 的字段值开始处。
// 调用后若该字段存在，Decoder 正停在该字段值的第一个 token 上（调用方可用
// dec.Token/dec.Decode 读取）；若字段不存在，顶层对象已经读完（dec.More()
// 为 false）。field 之外的字段整值跳过，不深入其内部。
func skipToObjectField(dec *json.Decoder, field string) error {
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	if d, isDelim := tok.(json.Delim); !isDelim || d != '{' {
		return fmt.Errorf("water: 数据文件顶层应为 JSON 对象")
	}
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return err
		}
		if keyTok.(string) == field {
			return nil
		}
		var skip json.RawMessage
		if err := dec.Decode(&skip); err != nil {
			return err
		}
	}
	return nil
}

